use std::collections::HashSet;

fn main() {
    let connection = rusqlite::Connection::open_in_memory().unwrap();
    connection.execute_batch(include_str!("snapshot/schema.sql")).unwrap();
    for count in [1000, 32767] {
        let paths: HashSet<String> = (0..count).map(|index| format!("file_{index}.py")).collect();
        match agent_weave::db::load_carried(&connection, &paths) {
            Ok(_) => println!("carried_paths={count} result=ok"),
            Err(error) => println!("carried_paths={count} result={error}"),
        }
    }
}

thin_library_probe_sources.impact_probe.rs:
use std::path::Path;

fn main() {
    for (module_id, function_id) in [(1, 2), (2, 1)] {
        let connection = rusqlite::Connection::open_in_memory().unwrap();
        connection.execute_batch(include_str!("snapshot/schema.sql")).unwrap();
        connection.execute_batch(include_str!("snapshot/schema_indexes.sql")).unwrap();
        connection.execute_batch(
            "INSERT INTO files(id,path,size,mtime,content_hash,parse_status,error_nodes)
             VALUES(1,'target.py',0,0,0,'ok',0),(2,'caller.py',0,0,0,'ok',0);"
        ).unwrap();
        connection.execute(
            "INSERT INTO symbols(id,kind,name,qualname,file_id,file_path,line_start,line_end)
             VALUES(?1,'module','target','target',1,'target.py',1,1)", [module_id]
        ).unwrap();
        connection.execute(
            "INSERT INTO symbols(id,kind,name,qualname,file_id,file_path,line_start,line_end)
             VALUES(?1,'function','f','target.f',1,'target.py',1,1)", [function_id]
        ).unwrap();
        connection.execute_batch(
            "INSERT INTO symbols(id,kind,name,qualname,file_id,file_path,line_start,line_end)
             VALUES(3,'module','caller','caller',2,'caller.py',1,1);"
        ).unwrap();
        for (destination, name, kind) in [
            (module_id, "target", "imports"),
            (function_id, "target.f", "imports"),
            (function_id, "target.f", "calls"),
        ] {
            connection.execute(
                "INSERT INTO edges(src_id,dst_id,dst_name,kind,confidence,site_line)
                 VALUES(3,?1,?2,?3,'EXTRACTED',1)",
                rusqlite::params![destination, name, kind]
            ).unwrap();
        }
        let output = agent_weave::query::impact(
            &connection, Path::new("."), "target.py", 50, false, 2, "all", false, true
        ).unwrap();
        for pointer in output.pointers {
            println!("module_id={module_id} function_id={function_id} {}", pointer.render());
        }
    }
}
